/**
 * PRISM themes. Generated by build.py (outside this repo), then brought in by
 * hand on 2026-10-06 with one change: Coral reef's light-mode accent moved from
 * #D44A2E to #D06A35 (hue 10° to 21°) so it no longer reads as an error red.
 * It keeps every contrast rule below. Change themes here, or regenerate and
 * reapply that fix.
 *
 * Rules every theme follows:
 *  - Components read semantic tokens only, never hex values.
 *  - `accent` is for fills, icons and rings. Text in the accent colour uses `accentText`.
 *  - Status tokens (success, warning, danger) keep their meaning in every theme.
 *    Never rely on colour alone: pair them with an icon and a label.
 *  - Never use `danger` or `warning` for a missed dose. A missed dose is not a failure.
 *  - Never give a theme a multi-colour gradient treatment. Single colours only.
 *
 * Contrast, verified by script: text 12.8:1 or better, secondary text 5.5:1 or better,
 * muted text 4.5:1, accent fills 3:1, accentText and status 4.5:1, text on accent fill 4.5:1.
 */

export type Mode = 'dark' | 'light';
export type Tier = 'free' | 'plus';
export type ThemeId =
  | 'prism'
  | 'ember'
  | 'tidepool'
  | 'dusk'
