export const DEFAULT_THEME: ThemeId = 'prism';

export function getTokens(id: ThemeId, mode: Mode): Tokens {
  return themes[id][mode];
}

/** `system` resolves to the OS setting. Store `mode` and `themeId` as separate fields. */
export function resolveMode(setting: Mode | 'system', osMode: Mode): Mode {
  return setting === 'system' ? osMode : setting;
}

/** Every theme, in the order the picker shows them. */
export const THEME_IDS = Object.keys(themes) as ThemeId[];

export function isThemeId(value: unknown): value is ThemeId {
  return typeof value === 'string' && value in themes;
}
